  flashcards: [
    { id: "human-computer-interaction-fc-1", front: "HCI (SIGCHI working definition, paraphrased)", back: "A discipline concerned with the design, evaluation and implementation of interactive computing systems for human use, and with the study of the major phenomena surrounding them." },
    { id: "human-computer-interaction-fc-2", front: "Cognitive modelling in HCI", back: "Treats the user as an information processor and predicts performance (Card, Moran and Newell 1983): Model Human Processor, GOMS, keystroke-level model." },
    { id: "human-computer-interaction-fc-3", front: "Bødker's second and third waves", back: "Second wave: groups and work settings. Third wave: broader, more varied use contexts, with experience and participation. Second-wave ideas can still contribute." },
    { id: "human-computer-interaction-fc-4", front: "Why 'one HCI' is a simplification (Grudin 2005)", back: "Research on human-computer interaction grew in several communities with different foci: computer operation, information systems management, discretionary use." },
    { id: "human-computer-interaction-fc-5", front: "The four elements of an interaction", back: "Person, task, technology and context of use. A finding is always about a particular combination; change one and the others shift." },
    { id: "human-computer-interaction-fc-6", front: "Choosing an HCI method", back: "Start from the question, not the technique: performance comparisons suit controlled experiments; fit with work suits field study; reported views suit interviews or surveys; experience over time suits diary studies." },
    { id: "human-computer-interaction-fc-7", front: "Unit of analysis: cognitive vs situated", back: "Cognitive modelling: the individual information processor. Situated and distributed accounts: people with others, tools and setting (Suchman 1987; Hutchins 1995)." },
    { id: "human-computer-interaction-fc-8", front: "Event versus interpretation in HCI history", back: "A dated milestone (e.g. Sketchpad, 1963) is an event. 'Waves' and 'paradigms' are interpretive frameworks; accounts differ and the periods overlap." },
  ],

